```rust
use std::io::{self, Read};
use blake3::Hasher;

/// Stream-reads a `Read`-based source through BLAKE3 in 64KB chunks.
/// Returns a cryptographically secure 256-bit content digest.
/// 
/// # Memory Profile
/// Allocates exactly one fixed-size stack buffer (`[u8; 65_536]`).
/// O(1) heap usage regardless of input size (100 GB+ handled safely).
/// 
/// # Design Notes
/// - Uses `65_536` bytes because it matches typical filesystem block
///   alignment and avoids frequent page faults.
/// - Handles `Interrupted` errors gracefully per POSIX retry semantics.
/// - Finalizes via `extend_from_reader()` under the hood, but we loop
///   explicitly to surface errors and allow early-exit on corruption.
pub fn hash_streaming<R: Read>(reader: &mut R) -> Result<[u8; 32], ScanError> {
    let mut hasher = Hasher::new();
    let mut buf = [0u8; 65_536]; // Fixed 64KB stack buffer

    loop {
        match reader.read(&mut buf) {
            Ok(0) => break, // EOF reached naturally
            Ok(n) => {
                // SAFETY: `n > 0` guaranteed by `Read` contract when return is `Ok(n)`
                hasher.extend_from_slice(&buf[..n]);
            }
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(ScanError::Io(e)),
        }
    }

    // `finaliz().to_bytes()` converts the internal 512-bit state to a fixed [u8; 32]
    Ok(hasher.finalize().to_bytes())
}
```

