use std::fs::File;
use std::io::{self, Read};
use std::path::PathBuf;
use rayon::prelude::*;
use std::sync::{Arc, Semaphore};

/// Core streaming hasher (unchanged from previous section)
fn hash_streaming<R: Read>(reader: &mut R) -> Result<[u8; 32], ScanError> {
    let mut hasher = Hasher::new();
    let mut buf = [0u8; 65_536];
    loop {
        match reader.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => hasher.extend_from_slice(&buf[..n]),
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(ScanError::Io(e)),
        }
    }
    Ok(hasher.finalize().to_bytes())
}

/// Capped parallel dispatcher. Prevents I/O thrashing while maximizing CPU throughput.
pub fn hash_paths_parallel(paths: &[PathBuf], disk_io_cap: usize) -> Result<Vec<(PathBuf, [u8; 32])>, ScanError> {
    // Semaphore blocks extra open+read syscalls until a worker frees up.
    let semaphore = Arc::new(Semaphore::new(disk_io_cap));

    paths.par_iter().map(|path| {
        // Acquire permit. Blocks synchronously if at cap (never returns Err, just waits).
        let _permit = semaphore.acquire();

        let mut reader = File::open(path)?;
        let digest = hash_streaming(&mut reader)?;
        Ok((path.clone(), digest))
    }).collect::<Result<Vec<_>, ScanError>>()
}
```

